-- Generated by scripts/rubric-registry-generator.cjs. Do not hand edit.
-- criteria-pipeline-v2: 634 exercise variants and 7608 resolved visual criteria.

create table if not exists public.exercise_variants_v2 (
  id integer primary key,
  slug text not null unique,
  name text not null,
  category text not null check (category in ('Chest', 'Back', 'Legs', 'Shoulders', 'Arms', 'Core')),
  family text not null,
  aliases jsonb not null default '[]'::jsonb check (jsonb_typeof(aliases) = 'array'),
  mechanics jsonb not null check (jsonb_typeof(mechanics) = 'object'),
  mechanics_key text not null unique,
  rubric_version integer not null default 2 check (rubric_version = 2),
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists public.exercise_criteria_v2 (
  id text primary key,
  exercise_id integer not null references public.exercise_variants_v2(id) on delete cascade,
  phase text not null,
  domain text not null check (domain in ('setup_stability', 'path_alignment', 'range_positions', 'control_tempo', 'rep_consistency')),
  inspection_question text not null,
  visible_good text not null,
  visible_issue text not null,
  applicability_tags jsonb not null check (jsonb_typeof(applicability_tags) = 'array'),
  exclusion_tags jsonb not null check (jsonb_typeof(exclusion_tags) = 'array'),
  visibility_by_camera jsonb not null check (jsonb_typeof(visibility_by_camera) = 'object'),
  severity_cap text not null check (severity_cap in ('minor', 'important', 'major')),
  coaching_cue text not null,
  source_refs jsonb not null check (jsonb_typeof(source_refs) = 'array'),
  editorial_status text not null check (editorial_status = 'reviewed'),
  specificity text not null check (specificity in ('movement', 'equipment', 'variation')),
  rubric_version integer not null default 2 check (rubric_version = 2),
  created_at timestamptz not null default now()
);

create index if not exists exercise_criteria_v2_exercise_idx on public.exercise_criteria_v2(exercise_id, domain);

create table if not exists public.analysis_stage_runs (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.analysis_sessions(id) on delete cascade,
  pipeline_version text not null,
  stage text not null check (stage in ('indexing', 'rubric_ready', 'analyzing', 'validating_candidates', 'verifying', 'extracting_display_frames', 'scoring', 'writing_coaching')),
  input_checksum text not null,
  status text not null check (status in ('queued', 'running', 'succeeded', 'failed')),
  attempt integer not null default 0 check (attempt between 0 and 2),
  output jsonb,
  error_code text,
  started_at timestamptz,
  completed_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (session_id, pipeline_version, stage, input_checksum)
);

create index if not exists analysis_stage_runs_resume_idx on public.analysis_stage_runs(session_id, pipeline_version, stage, status);

create table if not exists public.model_call_telemetry (
  id uuid primary key default gen_random_uuid(),
  session_id uuid not null references public.analysis_sessions(id) on delete cascade,
  stage_run_id uuid references public.analysis_stage_runs(id) on delete set null,
  stage text not null,
  model text not null,
  requested_fps numeric,
  clip_start_ms integer,
  clip_end_ms integer,
  prompt_tokens integer check (prompt_tokens is null or prompt_tokens >= 0),
  output_tokens integer check (output_tokens is null or output_tokens >= 0),
  thinking_tokens integer check (thinking_tokens is null or thinking_tokens >= 0),
  duration_ms integer check (duration_ms is null or duration_ms >= 0),
  estimated_cost_usd numeric check (estimated_cost_usd is null or estimated_cost_usd >= 0),
  status text not null check (status in ('succeeded', 'failed')),
  error_code text,
  created_at timestamptz not null default now()
);

alter table public.exercise_variants_v2 enable row level security;
alter table public.exercise_criteria_v2 enable row level security;
alter table public.analysis_stage_runs enable row level security;
alter table public.model_call_telemetry enable row level security;

drop policy if exists "Active v2 exercises are publicly readable" on public.exercise_variants_v2;
create policy "Active v2 exercises are publicly readable"
on public.exercise_variants_v2 for select to anon, authenticated using (is_active = true);

drop policy if exists "Users can read own stage runs" on public.analysis_stage_runs;
create policy "Users can read own stage runs"
on public.analysis_stage_runs for select to authenticated
using (exists (select 1 from public.analysis_sessions s where s.id = analysis_stage_runs.session_id and s.user_id = (select auth.uid())));

grant select on public.exercise_variants_v2 to anon, authenticated;
grant select on public.exercise_criteria_v2 to service_role;
grant select, insert, update, delete on public.analysis_stage_runs to service_role;
grant select, insert, update, delete on public.model_call_telemetry to service_role;

