insert into public.exercise_criteria_v2 (
  id, exercise_id, phase, domain, inspection_question, visible_good, visible_issue,
  applicability_tags, exclusion_tags, visibility_by_camera, severity_cap, coaching_cue,
  source_refs, editorial_status, specificity, rubric_version
)
select
  id, exercise_id, phase, domain, inspection_question, visible_good, visible_issue,
  applicability_tags, exclusion_tags, visibility_by_camera, severity_cap, coaching_cue,
  source_refs, editorial_status, specificity, 2
from jsonb_to_recordset($criteria$[{"id":"flat-barbell-bench-press:stable-start","exercise_id":1,"phase":"setup","domain":"setup_stability","inspection_question":"Does the lifter establish a repeatable, visibly supported starting position before each repetition?","visible_good":"The visible support points and starting position remain stable before each repetition.","visible_issue":"The starting position or visible support points shift before multiple repetitions begin.","applicability_tags":["press","barbell","bench-supported","free-path","bilateral","standard","standard","flat"],"exclusion_tags":[],"visibility_by_camera":{"front":"clear","side":"clear","rear":"clear","front-45":"clear","rear-45":"clear"},"severity_cap":"important","coaching_cue":"Reset the same supported starting position before every repetition.","source_refs":["FORM-visible-movement-standard-v2"],"editorial_status":"reviewed","specificity":"movement"},{"id":"flat-barbell-bench-press:controlled-return","exercise_id":1,"phase":"return","domain":"control_tempo","inspection_question":"Does the return phase remain visibly controlled instead of dropping, bouncing, or being pulled by the equipment?","visible_good":"The return phase stays controlled through the visible range.","visible_issue":"The return phase repeatedly drops, bounces, or accelerates beyond visible control.","applicability_tags":["press","barbell","bench-supported","free-path","bilateral","standard","standard","flat"],"exclusion_tags":[],"visibility_by_camera":{"front":"clear","side":"clear","rear":"clear","front-45":"clear","rear-45":"clear"},"severity_cap":"important","coaching_cue":"Own the return and keep the same controlled speed to the reset.","source_refs":["FORM-visible-movement-standard-v2"],"editorial_status":"reviewed","specificity":"movement"},{"id":"flat-barbell-bench-press:repeatable-cycles","exercise_id":1,"phase":"whole set","domain":"rep_consistency","inspection_question":"Do comparable repetitions preserve the same visible sequence, path, and endpoints as fatigue develops?","visible_good":"Comparable repetitions keep a repeatable visible sequence and endpoints.","visible_issue":"The visible sequence or endpoints change substantially across later repetitions.","applicability_tags":["press","barbell","bench-supported","free-path","bilateral","standard","standard","flat"],"exclusion_tags":[],"visibility_by_camera":{"front":"clear","side":"clear","rear":"clear","front-45":"clear","rear-45":"clear"},"severity_cap":"important","coaching_cue":"Repeat the same path and endpoints on the next set.","source_refs":["FORM-visible-movement-standard-v2"],"editorial_status":"reviewed","specificity":"movement"},{"id":"flat-barbell-bench-press:press-stack","exercise_id":1,"phase":"loaded transition","domain":"path_alignment","inspection_question":"Do the visible wrists or handles remain stacked over the forearms through the loaded transition?","visible_good":"The visible wrist, forearm, and handle relationship remains stable through the transition.","visible_issue":"The wrist or handle repeatedly shifts outside the visible forearm line during the loaded transition.","applicability_tags":["press","barbell","bench-supported","free-path","bilateral","standard","standard","flat"],"exclusion_tags":[],"visibility_by_camera":{"front":"clear","side":"clear","rear":"clear","front-45":"clear","rear-45":"clear"},"severity_cap":"important","coaching_cue":"Keep the handle or implement stacked over your forearm.","source_refs":["FORM-visible-movement-standard-v2"],"editorial_status":"reviewed","specificity":"movement"},{"id":"flat-barbell-bench-press:press-endpoint","exercise_id":1,"phase":"pressing phase","domain":"range_positions","inspection_question":"Does each repetition reach a repeatable visible pressing endpoint without the support position changing?","visible_good":"The pressing endpoint repeats while the support position stays stable.","visible_issue":"The pressing endpoint shortens or shifts while th