on conflict (id) do update set
  exercise_id = excluded.exercise_id,
  phase = excluded.phase,
  domain = excluded.domain,
  inspection_question = excluded.inspection_question,
  visible_good = excluded.visible_good,
  visible_issue = excluded.visible_issue,
  applicability_tags = excluded.applicability_tags,
  exclusion_tags = excluded.exclusion_tags,
  visibility_by_camera = excluded.visibility_by_camera,
  severity_cap = excluded.severity_cap,
  coaching_cue = excluded.coaching_cue,
  source_refs = excluded.source_refs,
  editorial_status = excluded.editorial_status,
  specificity = excluded.specificity,
  rubric_version = 2;

update public.exercise_profiles set is_active = false where is_active = true;
